from data_access.database import get_games, get_sessies, add_sessie, update_sessiefrom domain.sessie import Sessiedef toon_menu():    print("\n=== Game Tracker ===")    print("1. Games tonen")    print("2. Sessies tonen")    print("3. Sessie toevoegen")    print("4. Sessie wijzigen")    print("0. Stoppen")def toon_games():    print("\nGames:")    for game in get_games():        print(f"{game.id}. {game}")def toon_sessies():    print("\nSessies:")    for sessie in get_sessies():        print(f"{sessie.id}. {sessie}")def sessie_toevoegen():    toon_games()    try:        game_id = int(input("Kies het nummer van de game: "))        datum = input("Datum (JJJJ-MM-DD): ")        minuten = int(input("Aantal minuten: "))    except ValueError:        print("Geef een geldig getal in.")        return    antwoord = input("Gewonnen? (j/n): ")    gewonnen = antwoord == "j"    sessie = Sessie(game_id, datum, minuten, gewonnen)    add_sessie(sessie)    print("Sessie toegevoegd!")def sessie_wijzigen():    toon_sessies()    try:        sessie_id = int(input("Welke sessie wil je wijzigen (nummer)? "))    except ValueError:        print("Geef een geldig getal in.")        return        gekozen = None    for sessie in get_sessies():        if sessie.id == sessie_id:            gekozen = sessie        if gekozen is None:        print("Sessie niet gevonden.")        return    try:        gekozen.minuten = int(input("Nieuw aantal minuten: "))    except ValueError:        print("Geef een geldig getal in.")        return        antwoord = input("Gewonnen? (j/n): ")    gekozen.gewonnen = antwoord == "j"        update_sessie(gekozen)    print("Sessie gewijzigd!")        def start():    while True:        toon_menu()        keuze = input("Maak een keuze: ")        if keuze == "1":            toon_games()        elif keuze == "2":            toon_sessies()        elif keuze == "3":            sessie_toevoegen()        elif keuze == "4":            sessie_wijzigen()        elif keuze == "0":            print("Tot ziens!")            break        else:            print("Ongeldige keuze, probeer opnieuw.")